namespace ghidra.app.plugin.core.datamgr.actions;



using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.util;

public class CreateCategoryAction : DockingAction {

	private static readonly string NEW_CATEGORY = "New Category";

	public CreateCategoryAction(DataTypeManagerPlugin plugin) : base("New Category", plugin.getName())
    {

		setPopupMenuData(new MenuData(new string[] { "New", "Category" }, null, "Create"));
		setDescription("Creates a new Category.");
		setEnabled(true);
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		CategoryNode categoryNode = getSelectedCategoryNode(context);
		if (categoryNode == null || !categoryNode.isEnabled()) {
			return false;
		}
		if (categoryNode is BuiltInArchiveNode) {
			return false;
		}
		return true;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		CategoryNode categoryNode = getSelectedCategoryNode(context);
		return categoryNode != null && categoryNode.isModifiable();
	}

	private CategoryNode getSelectedCategoryNode(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return null;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;

		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths.length != 1) {
			return null;
		}
		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();

		if (!(node is CategoryNode)) {
			return null;
		}
		return (CategoryNode) node;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		DataTypeArchiveGTree gtree = (DataTypeArchiveGTree) context.getContextObject();
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		CategoryNode node = (CategoryNode) selectionPaths[0].getLastPathComponent();
		Category category = node.getCategory();
		DataTypeStoreNode dataStoreNode = node.getArchiveNode();
		DataTypeManager dataTypeManager = dataStoreNode.getDataTypeManager();

		string newNodeName = getUniqueCategoryName(category);
		string path = category.toString() + newNodeName;
		int transactionID = dataTypeManager.startTransaction("Create " + path);
		try {
			category.createCategory(newNodeName);
		}
		catch (InvalidNameException ie) {
			// can't happen since we created a unique valid name.
		}
		finally {
			dataTypeManager.endTransaction(transactionID, true);
		}

		dataTypeManager.flushEvents();
		gtree.startEditing(node, newNodeName);
	}

	private string getUniqueCategoryName(Category parent) {
		int index = 1;
		string name = NEW_CATEGORY;

		Category category = parent.getCategory(name);
		while (category != null) {
			name = NEW_CATEGORY + index;
			++index;
			category = parent.getCategory(name);
		}
		return name;
	}
}
